DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.product_asset_declaration_valid(text,text,text,text,text,text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='a8908cf7e45b4ef328e0128c45f4041a7a87a3acb9cdf39ba637efdd0f1d630b' AND provolatile='s' AND proisstrict=false AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:product_asset_declaration_valid'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.internal_review_valid(qf.draft_review)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='55c6ef9a2ac422fd9cc220620f6ae35b3677f174e5d976d21775b3935bd42a0c' AND provolatile='i' AND proisstrict=true AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:internal_review_valid'; END IF; END $$;
