CREATE OR REPLACE FUNCTION qf.composed_assets_v1(source jsonb,chosen_character jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE neutral jsonb; refs jsonb; assets jsonb;
BEGIN
 neutral:=source#>'{bindings,slots,neutral}';
 refs:=jsonb_build_array(neutral->'cover',neutral->'reportPaper',neutral->'reportBorder',neutral->'seal',chosen_character->'reveal',chosen_character->'nameArt',chosen_character->'report',chosen_character->'poster');
 IF chosen_character ? 'revealComposite' THEN refs:=refs||jsonb_build_array(chosen_character#>'{revealComposite,before}',chosen_character#>'{revealComposite,full}'); END IF;
 IF neutral ? 'preferenceScene' THEN refs:=refs||jsonb_build_array(neutral->'preferenceScene'); END IF;
 SELECT refs||coalesce(jsonb_agg(ref),'[]') INTO refs FROM jsonb_array_elements(neutral->'acts') a CROSS JOIN LATERAL (VALUES(a->'background'),(a->'questionPaper'),(a->'optionIdle'),(a->'optionSelected')) r(ref);
 SELECT jsonb_agg(jsonb_build_object('resourceRef',jsonb_build_object('productId',r->'productId','id',r->'id','version',r->'version'),'mediaType',r->'mediaType','bytes',r->'bytes','sha256',r->'sha256','width',r->'width','height',r->'height','purpose',r->'purpose','approval',r->'approval','alt',d->'alt') ORDER BY n) INTO assets FROM jsonb_array_elements(source#>'{bindings,resources}') WITH ORDINALITY resource(r,n) JOIN LATERAL jsonb_array_elements(source#>'{bindings,visualPresentation,resourceDescriptions}') d ON d->'resourceRef'=jsonb_build_object('productId',r->'productId','id',r->'id','version',r->'version') WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(refs) ref WHERE ref=jsonb_build_object('productId',r->'productId','id',r->'id','version',r->'version'));
 RETURN assets;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION qf.private_test_database_valid() RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT (current_database()='qf_db_953991305a7e8c49bb773d95cd120378' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:953991305a7e8c49bb773d95cd120378:test') OR (current_database()='qf_db_bea112ce460725bd10fc41226e45df48' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:bea112ce460725bd10fc41226e45df48:test') $$;

CREATE OR REPLACE FUNCTION qf.private_test_structure_valid(source jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE marked boolean; private_count integer; total integer;
BEGIN
 marked:=(source->'bindings') ? 'privateTestUse';
 SELECT count(*)::integer,count(*) FILTER(WHERE r->>'approval'='private-test-only')::integer INTO total,private_count FROM jsonb_array_elements(source#>'{bindings,resources}') r;
 IF NOT marked THEN RETURN private_count=0; END IF;
 RETURN (total>0 AND total=private_count AND source#>>'{bindings,kind}'='authored'
  AND (source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-full-flow-20261030","contentStatus":"candidate","instanceId":"953991305a7e8c49bb773d95cd120378","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb OR source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-prototype-rebuild-20261031","contentStatus":"candidate","instanceId":"bea112ce460725bd10fc41226e45df48","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb)
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{bindings,resources}') r WHERE r#>'{license,commercialUse}' IS DISTINCT FROM 'false'::jsonb OR r#>'{license,redistribution}' IS DISTINCT FROM 'false'::jsonb OR r#>>'{license,scope}' IS DISTINCT FROM 'private-test-only')) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.private_test_source_valid(source jsonb,asset_sha text,manifest_sha text) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF coalesce((source->'bindings') ? 'privateTestUse',false) IS FALSE THEN RETURN true; END IF;
 RETURN (qf.private_test_structure_valid(source) AND (((current_database()='qf_db_953991305a7e8c49bb773d95cd120378' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:953991305a7e8c49bb773d95cd120378:test') AND source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-full-flow-20261030","contentStatus":"candidate","instanceId":"953991305a7e8c49bb773d95cd120378","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb AND qf.sha256_utf8(qf.consumer_canonical(source))='112c9da91f0346f780b050e340d820d20c19a144695b94c48a86a53c91040633' AND asset_sha='da03e7f4af5e621a714ec93ce7368a7f594d5f97de9b4a8534b586abf5a405a3' AND manifest_sha='351ebfcd1dd17036fceb896f0a9a50e419b628fe1260d87dd37db59cf0de5fb5') OR ((current_database()='qf_db_bea112ce460725bd10fc41226e45df48' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:bea112ce460725bd10fc41226e45df48:test') AND source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-prototype-rebuild-20261031","contentStatus":"candidate","instanceId":"bea112ce460725bd10fc41226e45df48","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb AND qf.sha256_utf8(qf.consumer_canonical(source))='e81fad61f2258e44ba58fe84fda12fedccfb0d7517e97546010f4fa35cfbe767' AND asset_sha='df91c856f78eec8fb3f13d405991d9a8ef97a07353c16762755886360a8961f4' AND manifest_sha='aa6071d9f3e0d71696dd78782086efb7b3b6aafe8bbf0d313234a8dc32279814'))) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.product_asset_declaration_valid(pid text, rid text, ver text, sha text, purpose text, declaration text) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE d jsonb; b qf.asset_blob;
BEGIN
 IF declaration IS NULL OR octet_length(declaration) NOT BETWEEN 2 AND 65536 THEN RETURN false; END IF;
 d:=declaration::jsonb; SELECT * INTO b FROM qf.asset_blob WHERE sha256=sha;
 RETURN (jsonb_typeof(d)='object' AND d->>'id'=rid AND d->>'productId'=pid AND d->>'version'=ver AND d->>'sha256'=sha AND d->>'purpose'=purpose
  AND d->'bytes'=to_jsonb(b.bytes) AND d->>'mediaType'=b.media_type AND d->'width'=to_jsonb(b.width) AND d->'height'=to_jsonb(b.height) AND b.frames=1
  AND ((d#>'{license,commercialUse}'='true'::jsonb AND d#>'{license,redistribution}'='true'::jsonb AND d->>'approval' IN ('pending','approved')) OR (qf.private_test_database_valid() AND d->>'approval'='private-test-only' AND d#>'{license,commercialUse}'='false'::jsonb AND d#>'{license,redistribution}'='false'::jsonb AND d#>>'{license,scope}'='private-test-only' AND qf.sha256_utf8(qf.consumer_canonical(d)) IN ('737b559d62fda0d3e1e6be5517fc504b8a301f0b91210a07fe710e9fbeea6ba4','dd268320e2217da78246d911083314e630f9594972a8515ebf2b1986b9a0004c','2175d10d86c24ebfd3bf30a8cffdc489a96fef05415e80cb67297cc9536055f7','812c4257b8261adcc84fd162fe37b8e8c5b021ff4fc128643f7c11703938f2b2','52fec226547b407902310c3cc9367787edeb18763b145be82f504d12c5512f23','3a7952e93a23c09128e3f5184ba59fc0aaaaefbb2cdca9617079fee68eba2897','edad554862fc93f9f628b2445a0fe5eb5807a47727edd67e38b8e806e4eba771','1bd77cb75749d026620fffc21b71cbf413647b92370d5ee5f809b8a088ae4626','8516c619c7777c03152f4ab07a767f199cbdf90bf4d9f5f56763848248b2c10b','4f2d591976f94868c36fd1f50efecc2f138815364b03b22f8bd54c33af0a114b','3c91fa57072914ec3bb44ea4341c5c7f7a956691c6b31e450ff0c2690ec8c870','aaba59ea8756f64c0c69575fc376250c720ed92280abb476b5a11f58ff7992e7','b795f93147da5b1680af73c848118666a499f43fa49e3c8d114de53ecfdbf04d','e976b7944b2abfd6787c05ad4e7ea8f6a4ac17c6faa5d6230c7a303950b206b6','d1ae74a9df545b877d34da3a5890932eff635438e79b0936c3cc3f8bf862f5a6','4506dab0aea7d42582d05a9fe60ed92e4668587c10ed8dc8558500eb59c2db8c','49d96616a7cfe9f4387beb45866cf3dabe4832fa6f436e3381b7c007b9e7edb0','43e328b8ef3472f01afc5778ecfb512ae38e2e5bfaf1383a450e111cc1233508','2db57f984db51dd6491bb28c7c6badaf7e4d8d208f8bd3ca803fcf710c45ac0a','90248e7673c7ce983e23d7aa2ff91d4b6bc31d9d241773d464d94641427581f7','0a7fcd8e00102ce7a19bb7c7bd1a4763a93ec6078ce3d0ec9ca955209fc7c412','b92fdd93f0b21740b48dd29e62bd98e9c78bf14a441fc9735eb6b4d6235bfeed','4d2c5feee0c1e1d39d7af874172b987fc1893650bc85a30ead0b50da368cc72c','f90db0d215559b6f0955a93039486d3f03cbe784bddffcb9f486444738a0aea5','01997ba2538aeb4beb69f535af9b8d4e7982284e162c07f10cf7f3274324d6c2','8d7a7d756ae5bcfd7648de5aa4a89298f3cb31aa5d974676fef72b83caea7248','6939316ddde996b93448adc961439d2f66fad3d6a4f10baa883436ac3220a5e7')))) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.internal_review_valid(r qf.draft_review) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; f jsonb; t jsonb; a jsonb;
BEGIN
 b:=r.binding_text::jsonb; f:=r.facts_text::jsonb; a:=f->'approval';
 t:=jsonb_build_object('draftId',r.draft_id,'revision',r.revision,'canonicalContentSha256',r.canonical_content_sha256::text,'assetSetSha256',r.asset_set_sha256::text,'canonicalManifestSha256',r.canonical_manifest_sha256::text);
 RETURN (r.binding_text=qf.internal_canonical(b) AND r.fingerprint::text=qf.sha256_utf8(r.binding_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.review-record.v1','productId',r.product_id,'idempotencyKey',r.idempotency_key,'target',t,'baseline',b->'baseline')
 AND qf.internal_registry_identity(b->'baseline','baseline')
 AND r.facts_text=qf.internal_canonical(f) AND r.review_sha256::text=qf.sha256_utf8(r.facts_text)
 AND f=jsonb_build_object('schemaVersion','quizforge.internal-review-facts.v1','productId',r.product_id,'target',t,'baseline',b->'baseline','purpose',r.purpose,'approval',a)
 AND ((a='{"authorizationId":"qztx-prototype-rebuild-20261031","evidenceSha256":"753fd40e4387d47ed2a939e9363a3b79068ad121e91baa68c664ef55e1e072c2","instanceId":"bea112ce460725bd10fc41226e45df48","kind":"private-test-only","scope":"candidate-content-reference-art-local-test-only"}'::jsonb AND r.product_id='qianzai-tongxin' AND r.canonical_content_sha256::text='e81fad61f2258e44ba58fe84fda12fedccfb0d7517e97546010f4fa35cfbe767' AND r.asset_set_sha256::text='df91c856f78eec8fb3f13d405991d9a8ef97a07353c16762755886360a8961f4' AND r.canonical_manifest_sha256::text='aa6071d9f3e0d71696dd78782086efb7b3b6aafe8bbf0d313234a8dc32279814' AND b->'baseline'='{"entrySha256":"594240edcab08050b16a9f972c515f98643bc10cb94557759790722d28ae6cd8","id":"qztx-private-rebuild-20261031","kind":"baseline","version":"1.0.0"}'::jsonb) OR (a='{"authorizationId":"qztx-full-flow-20261030","evidenceSha256":"5c321443c5931ce5622bb8bab0741366e9897c08672abeefb26363be8a86e0fb","instanceId":"953991305a7e8c49bb773d95cd120378","kind":"private-test-only","scope":"candidate-content-reference-art-local-test-only"}'::jsonb AND r.canonical_content_sha256::text='112c9da91f0346f780b050e340d820d20c19a144695b94c48a86a53c91040633' AND r.asset_set_sha256::text='da03e7f4af5e621a714ec93ce7368a7f594d5f97de9b4a8534b586abf5a405a3' AND r.canonical_manifest_sha256::text='351ebfcd1dd17036fceb896f0a9a50e419b628fe1260d87dd37db59cf0de5fb5') OR (a->>'kind'='author-baseline' AND a=jsonb_build_object('kind','author-baseline','approvedOn',a->'approvedOn','sourceRecordId',a->'sourceRecordId','evidenceSha256',a->'evidenceSha256','scope','internal-test-content-and-visual-baseline') AND a->>'approvedOn' ~ '^\d{4}-\d{2}-\d{2}$' AND a->>'sourceRecordId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$')
 OR (a->>'kind'='synthetic-test' AND a=jsonb_build_object('kind','synthetic-test','fixtureId',a->'fixtureId','evidenceSha256',a->'evidenceSha256','scope','test-evidence-no-author-approval') AND a->>'fixtureId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'))
 AND a->>'evidenceSha256' ~ '^[a-f0-9]{64}$') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_internal_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r qf.draft_revision; v qf.quizpack_validation; review qf.draft_review; s jsonb; head integer; archived timestamptz;
BEGIN
 IF TG_TABLE_NAME='draft_review' THEN IF NEW.facts_text::jsonb#>>'{approval,kind}'='private-test-only' AND (qf.private_test_database_valid() IS NOT TRUE OR current_database() IS DISTINCT FROM 'qf_db_'||(NEW.facts_text::jsonb#>>'{approval,instanceId}')) THEN RAISE EXCEPTION 'PRIVATE_TEST_SCOPE' USING ERRCODE='23514'; END IF; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_INTERNAL_REFERENCE' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT archived_at INTO archived FROM qf.product WHERE id=NEW.product_id FOR UPDATE;
 IF NOT FOUND OR archived IS NOT NULL THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_PRODUCT_INACTIVE' USING ERRCODE='23514'; END IF;
 SELECT current_revision INTO head FROM qf.product_draft WHERE product_id=NEW.product_id AND id=NEW.draft_id;
 IF head IS DISTINCT FROM NEW.revision THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_HEAD_CHANGED' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM qf.draft_revision WHERE product_id=NEW.product_id AND draft_id=NEW.draft_id AND revision=NEW.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='draft_review' THEN
  IF (NEW.source_import_id,NEW.source_validation_id,NEW.source_validation_state_revision) IS DISTINCT FROM (r.source_import_id,r.source_validation_id,r.source_validation_state_revision) THEN RAISE EXCEPTION 'INTERNAL_REVIEW_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO review FROM qf.draft_review WHERE product_id=NEW.product_id AND id=NEW.review_id;
  SELECT * INTO v FROM qf.quizpack_validation WHERE product_id=r.product_id AND import_id=r.source_import_id AND id=r.source_validation_id;
  s:=NEW.snapshot_text::jsonb;
  IF review.id IS NULL OR v.id IS NULL OR s->'baseline' IS DISTINCT FROM review.facts_text::jsonb->'baseline'
   OR (s->>'packId',s->>'packVersion',s->>'contentSchemaVersion',s->>'contentKind') IS DISTINCT FROM (r.pack_id::text,r.pack_version::text,r.content_schema_version::text,r.content_kind::text)
   OR s->'versions' IS DISTINCT FROM jsonb_build_object('contentVersion',r.content_version,'visualVersion',r.visual_version,'reportVersion',r.report_version,'resourceVersion',r.resource_version,'componentVersion',r.component_version,'engine',jsonb_build_object('id',r.engine_id,'version',r.engine_version))
   OR s->'validation' IS DISTINCT FROM jsonb_build_object('sourceImportId',r.source_import_id,'sourceValidationId',r.source_validation_id,'sourceValidationStateRevision',r.source_validation_state_revision,'archiveSha256',v.archive_sha256::text,'candidateSha256',r.candidate_sha256::text,'identitySha256',v.identity_sha256::text,'validatorBundleSha256',v.identity_text::jsonb->>'validatorBundleSha256','archivePolicyVersion',v.archive_policy_version,'archivePolicySha256',v.archive_policy_sha256::text,'evidenceSha256',v.evidence_sha256::text)
  THEN RAISE EXCEPTION 'INTERNAL_VERSION_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.consumer_schema_v2(text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='08a756fbd5c3001d2b6604df619e54d817fb269219ddbcdfdf5f04b30b3d2510' AND provolatile='i' AND proisstrict=true AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='jsonb'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='sql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:consumer_schema_v2'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.composed_assets_v1(jsonb,jsonb)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='c8244465cd87bb53d64091d8ec7e4d39af88a0b8fa6e402d90aa2ba6d2db248f' AND provolatile='i' AND proisstrict=true AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='jsonb'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:composed_assets_v1'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.private_test_database_valid()'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='e4cb0736a9fed07f3cd3243ede1526ad43652dfd211b3fdab8439c328e1fb7ce' AND provolatile='s' AND proisstrict=false AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='sql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:private_test_database_valid'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.private_test_structure_valid(jsonb)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='d4c0989f01bef0104e14bb5b3baec5b2974e8a8c5226e28fdc34ebb114d7a4a8' AND provolatile='i' AND proisstrict=true AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:private_test_structure_valid'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.private_test_source_valid(jsonb,text,text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='c97c33a9e7d8ef42cec688644eaf28c59b92b9b58fa5e0396c2293debd8bdb29' AND provolatile='s' AND proisstrict=true AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:private_test_source_valid'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.product_asset_declaration_valid(text,text,text,text,text,text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='95fc448ab99b9825ddd43b3784703b15d0b235afc2698f40790a4276e0b65157' AND provolatile='s' AND proisstrict=false AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:product_asset_declaration_valid'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.internal_review_valid(qf.draft_review)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='8b1e2109e70c9ae370ed05f7a16ed193d071e3f51dad93f1797322981b4286b2' AND provolatile='i' AND proisstrict=true AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='boolean'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:internal_review_valid'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.protect_internal_reference()'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='1703f5baf1d8d3c1ed8a45c0be3707684d31c9eeec0a0557836c7e3d8e3e9b0e' AND provolatile='v' AND proisstrict=false AND NOT prosecdef AND NOT proretset AND NOT proleakproof AND prokind='f' AND pronargdefaults=0 AND prorettype='trigger'::regtype AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_HELPER_CHANGED:protect_internal_reference'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid IN ('qf.consumer_schema_v2(text)'::regprocedure,'qf.composed_assets_v1(jsonb,jsonb)'::regprocedure,'qf.private_test_database_valid()'::regprocedure,'qf.private_test_structure_valid(jsonb)'::regprocedure,'qf.private_test_source_valid(jsonb,text,text)'::regprocedure,'qf.product_asset_declaration_valid(text,text,text,text,text,text)'::regprocedure,'qf.internal_review_valid(qf.draft_review)'::regprocedure,'qf.protect_internal_reference()'::regprocedure) AND a.grantee=0) THEN RAISE EXCEPTION 'ROLE_COMPOSITE_PUBLIC_EXECUTE'; END IF; END $$;
DO $$ DECLARE v qf.quizpack_validation; a qf.draft_review; p qf.product_version; play qf.internal_play_version; r qf.quiz_report; BEGIN FOR v IN SELECT * FROM qf.quizpack_validation LOOP IF qf.validation_shape_valid(v) IS NOT TRUE THEN RAISE EXCEPTION 'ROLE_COMPOSITE_EXISTING_VALIDATION'; END IF; END LOOP; FOR a IN SELECT * FROM qf.draft_review LOOP IF qf.internal_review_valid(a) IS NOT TRUE THEN RAISE EXCEPTION 'ROLE_COMPOSITE_EXISTING_REVIEW'; END IF; END LOOP; FOR p IN SELECT * FROM qf.product_version LOOP IF qf.internal_version_valid(p) IS NOT TRUE THEN RAISE EXCEPTION 'ROLE_COMPOSITE_EXISTING_VERSION'; END IF; END LOOP; FOR play IN SELECT * FROM qf.internal_play_version LOOP IF qf.consumer_play_valid(play) IS NOT TRUE THEN RAISE EXCEPTION 'ROLE_COMPOSITE_EXISTING_PLAY'; END IF; END LOOP; FOR r IN SELECT * FROM qf.quiz_report LOOP IF qf.consumer_report_valid(r) IS NOT TRUE THEN RAISE EXCEPTION 'ROLE_COMPOSITE_EXISTING_REPORT'; END IF; END LOOP; END $$;
